import { spawn } from "node:child_process";

const env = { ...process.env, GBRAIN_HOME: process.env.HOME };
const child = spawn(
  "/harness-state/.bun/bin/gbrain",
  ["serve", "--surface", "starter", "--advertise", "verbs"],
  { env, stdio: ["pipe", "pipe", "pipe"] },
);

let buf = "";
const pending = new Map();
const stderr = [];
child.stderr.on("data", (d) => stderr.push(d.toString()));

function send(msg) {
  child.stdin.write(JSON.stringify(msg) + "\n");
}
function call(id, method, params) {
  return new Promise((resolve, reject) => {
    pending.set(id, { resolve, reject });
    send({ jsonrpc: "2.0", id, method, params });
    setTimeout(() => {
      if (pending.has(id)) {
        pending.delete(id);
        reject(new Error(`timeout on ${method}`));
      }
    }, 60000);
  });
}

child.stdout.on("data", (d) => {
  buf += d.toString();
  let i;
  while ((i = buf.indexOf("\n")) >= 0) {
    const line = buf.slice(0, i).trim();
    buf = buf.slice(i + 1);
    if (!line) continue;
    let msg;
    try {
      msg = JSON.parse(line);
    } catch {
      continue;
    }
    if (msg.id && pending.has(msg.id)) {
      const { resolve, reject } = pending.get(msg.id);
      pending.delete(msg.id);
      if (msg.error) reject(new Error(JSON.stringify(msg.error)));
      else resolve(msg.result);
    }
  }
});

const text = (r) => {
  const content = r?.content ?? [];
  const t = content.map((c) => c.text ?? "").join("\n");
  try {
    return JSON.parse(t);
  } catch {
    return t;
  }
};

try {
  const init = await call(1, "initialize", {
    protocolVersion: "2024-11-05",
    capabilities: {},
    clientInfo: { name: "roundtrip-check", version: "0.0.1" },
  });
  console.log("server:", JSON.stringify(init.serverInfo ?? init.capabilities));
  send({ jsonrpc: "2.0", method: "notifications/initialized", params: {} });

  const tools = await call(2, "tools/list", {});
  console.log("tools:", (tools.tools ?? []).map((t) => t.name).join(", "));

  const marker = "MCP round trip 2026-11-18: remember and recall work over the stdio transport.";
  const rem = await call(3, "tools/call", {
    name: "remember",
    arguments: {
      fact: marker,
      entity: "gbrain",
      provenance: "install-check",
      content_origin: "inferred",
    },
  });
  console.log("remember:", JSON.stringify(text(rem)).slice(0, 400));

  const rec = await call(4, "tools/call", {
    name: "recall",
    arguments: { entity: "gbrain" },
  });
  const recalled = text(rec);
  const facts = recalled.facts ?? [];
  const hit = facts.find((f) => String(f.fact).includes("MCP round trip 2026-11-18"));
  console.log("recall count:", recalled.total, "| mcp marker found:", Boolean(hit));
  console.log("MARKER_OK:", Boolean(hit));
} catch (e) {
  console.log("ERROR:", e.message);
  console.log("stderr:", stderr.join("").slice(-800));
  process.exitCode = 1;
} finally {
  child.stdin.end();
  setTimeout(() => process.exit(), 1500);
}

